pub(crate) fn cursor_style(value: &Value) -> Result<gpui::CursorStyle, RenderError> {
    Ok(match variant(value, "CursorStyle")? {
        "Arrow" => gpui::CursorStyle::Arrow,
        "IBeam" => gpui::CursorStyle::IBeam,
        "Crosshair" => gpui::CursorStyle::Crosshair,
        "ClosedHand" => gpui::CursorStyle::ClosedHand,
        "OpenHand" => gpui::CursorStyle::OpenHand,
        "PointingHand" => gpui::CursorStyle::PointingHand,
        "ResizeLeft" => gpui::CursorStyle::ResizeLeft,
        "ResizeRight" => gpui::CursorStyle::ResizeRight,
        "ResizeLeftRight" => gpui::CursorStyle::ResizeLeftRight,
        "ResizeUp" => gpui::CursorStyle::ResizeUp,
        "ResizeDown" => gpui::CursorStyle::ResizeDown,
        "ResizeUpDown" => gpui::CursorStyle::ResizeUpDown,
        "ResizeUpLeftDownRight" => gpui::CursorStyle::ResizeUpLeftDownRight,
        "ResizeUpRightDownLeft" => gpui::CursorStyle::ResizeUpRightDownLeft,
        "ResizeColumn" => gpui::CursorStyle::ResizeColumn,
        "ResizeRow" => gpui::CursorStyle::ResizeRow,
        "IBeamCursorForVerticalLayout" => gpui::CursorStyle::IBeamCursorForVerticalLayout,
        "OperationNotAllowed" => gpui::CursorStyle::OperationNotAllowed,
        "DragLink" => gpui::CursorStyle::DragLink,
        "DragCopy" => gpui::CursorStyle::DragCopy,
        "ContextualMenu" => gpui::CursorStyle::ContextualMenu,
        other => {
            return Err(RenderError::UnknownVariant(
                "CursorStyle",
                other.to_string(),
            ));
        }
    })
}

pub(crate) fn font_weight(value: &Value) -> Result<gpui::FontWeight, RenderError> {
    Ok(match variant(value, "FontWeight")? {
        "THIN" => gpui::FontWeight::THIN,
        "EXTRA_LIGHT" => gpui::FontWeight::EXTRA_LIGHT,
        "LIGHT" => gpui::FontWeight::LIGHT,
        "NORMAL" => gpui::FontWeight::NORMAL,
        "MEDIUM" => gpui::FontWeight::MEDIUM,
        "SEMIBOLD" => gpui::FontWeight::SEMIBOLD,
        "BOLD" => gpui::FontWeight::BOLD,
        "EXTRA_BOLD" => gpui::FontWeight::EXTRA_BOLD,
        "BLACK" => gpui::FontWeight::BLACK,
        other => return Err(RenderError::UnknownVariant("FontWeight", other.to_string())),
    })
}

pub(crate) fn text_align(value: &Value) -> Result<gpui::TextAlign, RenderError> {
    Ok(match variant(value, "TextAlign")? {
        "Left" => gpui::TextAlign::Left,
        "Center" => gpui::TextAlign::Center,
        "Right" => gpui::TextAlign::Right,
        other => return Err(RenderError::UnknownVariant("TextAlign", other.to_string())),
    })
}
